mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.PFLSH_NAME pflshName, DECODE(A.CREDIT_OBJ,'01',A.CREDIT_AMT/100000000,0) creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.CREDIT_PRICE creditPrice, A.HAP_CREDIT_AMT as hapCreditAmt, A.CREDIT_FLAG as creditFlag, C.FINPROD_NAME as customerName
,A.CREDIT_OBJ as creditObj ,DECODE(A.CREDIT_OBJ,'02',A.CREDIT_AMT/100000000,0) as creditShareAmt ,A.APPR_VDATE as apprVdate ,A.APPR_MDATE as apprMdate ,A.CREDIT_VDATE as creditVdate ,A.CREDIT_MDATE as creditMdate ,A.IS_LOOP_AMT as isLoopAmt ,A.HOLD_MATURITY as holdMaturity ,A.CREDIT_CONDITION as creditCondition
FROM CREDIT_LINES A
left join FIN_PRODUCT C on A.CUSTOMER_ID=C.FINPROD_ID
A.CREDIT_TYPE = '02'
AND A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND A.PFLSH_NAME LIKE CONCAT(CONCAT('%',#{pflshName}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}
AND A.CREDIT_OBJ = #{creditObj,jdbcType=VARCHAR}
AND DECODE(A.CREDIT_OBJ, '02', A.CREDIT_AMT / 100000000, 0) = #{creditShareAmt,jdbcType=DECIMAL}
AND A.HOLD_MATURITY = #{holdMaturity,jdbcType=VARCHAR}

mapper.update:
update CREDIT_LINES
CREDIT_AMT = #{creditAmt,jdbcType=DECIMAL}, CREDIT_SHARE_AMT = #{creditShareAmt,jdbcType=DECIMAL},
where SEQNO = #{seqno,jdbcType=VARCHAR}
